-- Republic of Aldoria (Politics, fictional country and parties)
-- Generated by gen_datasets.py with a fixed seed. Fictional data.

DROP TABLE IF EXISTS polls; DROP TABLE IF EXISTS results; DROP TABLE IF EXISTS elections; DROP TABLE IF EXISTS candidates;
DROP TABLE IF EXISTS parties; DROP TABLE IF EXISTS constituencies; DROP TABLE IF EXISTS regions;
CREATE TABLE regions (region_id INT PRIMARY KEY, region_name VARCHAR(60) COLLATE NOCASE NOT NULL, population INT);
CREATE TABLE constituencies (constituency_id INT PRIMARY KEY, region_id INT REFERENCES regions(region_id), constituency_name VARCHAR(60) COLLATE NOCASE, registered_voters INT);
CREATE TABLE parties (party_id INT PRIMARY KEY, party_name VARCHAR(60) COLLATE NOCASE NOT NULL, colour VARCHAR(60) COLLATE NOCASE, founded_year INT, split_from_party_id INT REFERENCES parties(party_id));
CREATE TABLE candidates (candidate_id INT PRIMARY KEY, party_id INT REFERENCES parties(party_id), first_name VARCHAR(60) COLLATE NOCASE, last_name VARCHAR(60) COLLATE NOCASE, gender VARCHAR(60) COLLATE NOCASE, birth_year INT);
CREATE TABLE elections (election_id INT PRIMARY KEY, election_name VARCHAR(60) COLLATE NOCASE, election_date DATE, election_type VARCHAR(60) COLLATE NOCASE);
CREATE TABLE results (result_id INT PRIMARY KEY, election_id INT REFERENCES elections(election_id), constituency_id INT REFERENCES constituencies(constituency_id),
  candidate_id INT REFERENCES candidates(candidate_id), votes INT);
CREATE TABLE polls (poll_id INT PRIMARY KEY, pollster VARCHAR(60) COLLATE NOCASE, fieldwork_end DATE, party_id INT REFERENCES parties(party_id), vote_share_pct DECIMAL(4,1), sample_size INT);








-- Raw sign-up import for Module 13 (Data Cleaning). Deliberately messy.
DROP TABLE IF EXISTS volunteer_signups;
CREATE TABLE volunteer_signups (signup_id INT PRIMARY KEY, full_name VARCHAR(60) COLLATE NOCASE, email VARCHAR(60) COLLATE NOCASE, phone VARCHAR(20), region VARCHAR(60) COLLATE NOCASE,
  signup_date VARCHAR(10), source VARCHAR(60) COLLATE NOCASE, pledge_amount VARCHAR(20));
